    _B = B;
    _defineProperty(B, 'prop', 2);
    _defineProperty(B, 'propA', _superPropGet(_B, 'prop', _B));
    _defineProperty(B, 'getPropA', () => _superPropGet(_B, 'prop', _B));
    const { prop, propA, getPropA } = B;
    expect(prop).toBe(2);
