    expect(
      class {
        static [foo]() {
          return 0;
        }
      }.foo(),
    ).toBe(0);
    expect(
      class {
        static get [foo]() {
          return 0;
        }
      }.foo,
    ).toBe(0);
    expect(
      (class {
        static set [foo](v) {
          return v;
        }
      }.foo = 0),
    ).toBe(0);
    expect(
      new (class {
        constructor() {
          _defineProperty(this, foo, 0);
        }
      })().foo,
    ).toBe(0);
    const arrayLike = { [Symbol.toPrimitive]: () => [] };
    expect(() => {
      var _Class2;
      return ((_Class2 = class {}), _defineProperty(_Class2, arrayLike, 0), _Class2);
    }).toThrow('@@toPrimitive must return a primitive value.');
    expect(
      () =>
        class {
          static [arrayLike]() {
            return 0;
          }
        },
    ).toThrow('@@toPrimitive must return a primitive value.');
    expect(
      () =>
        class {
          static get [arrayLike]() {
            return 0;
          }
        },
    ).toThrow('@@toPrimitive must return a primitive value.');
    expect(
      () =>
        class {
          static set [arrayLike](v) {
            return v;
          }
        },
    ).toThrow('@@toPrimitive must return a primitive value.');
