test('public/native-classes/exec.js [spec]', async () => {
  const source =
    'class Foo {\n  static foo = "foo";\n  bar = "bar";\n\n  static test() {\n    return Foo.foo;\n  }\n\n  test() {\n    return this.bar;\n  }\n}\n\nconst f = new Foo();\nexpect("foo" in Foo).toBe(true)\nexpect("bar" in f).toBe(true)\nexpect(Foo.test()).toBe("foo")\nexpect(f.test()).toBe("bar")\n';
  expect(
    await transformOutcome(source, 'exec.js', {
      transforms: { classProperties: { loose: false } },
      helpers: { mode: 'runtime', moduleName: '@babel/runtime', version: '7.29.7' },
    }),
  ).toMatchInlineSnapshot(`
    "var _defineProperty = require('@babel/runtime/helpers/defineProperty');
    class Foo {
      constructor() {
        _defineProperty(this, 'bar', 'bar');
      }
      static test() {
        return Foo.foo;
      }
      test() {
        return this.bar;
      }
    }
    _defineProperty(Foo, 'foo', 'foo');
    const f = new Foo();
    expect('foo' in Foo).toBe(true);
    expect('bar' in f).toBe(true);
    expect(Foo.test()).toBe('foo');
    expect(f.test()).toBe('bar');"
  `);
});

