test('public/update/exec.js [spec]', async () => {
  const source =
    'class Foo {\n  foo = 0;\n\n  test(other) {\n    return [\n      this.foo++,\n      this.foo,\n      ++this.foo,\n      this.foo,\n      other.obj.foo++,\n      other.obj.foo,\n      ++other.obj.foo,\n      other.obj.foo,\n    ];\n  }\n}\n\nconst f = new Foo;\nconst results = f.test({ obj: f });\nexpect(results[0]).toBe(0);\nexpect(results[1]).toBe(1);\nexpect(results[2]).toBe(2);\nexpect(results[3]).toBe(2);\nexpect(results[4]).toBe(2);\nexpect(results[5]).toBe(3);\nexpect(results[6]).toBe(4);\nexpect(results[7]).toBe(4);\n';
  expect(
    await transformOutcome(source, 'exec.js', {
      transforms: { classProperties: { loose: false } },
      helpers: { mode: 'runtime', moduleName: '@babel/runtime', version: '7.29.7' },
    }),
  ).toMatchInlineSnapshot(`
    "var _defineProperty = require('@babel/runtime/helpers/defineProperty');
    class Foo {
      constructor() {
        _defineProperty(this, 'foo', 0);
      }
      test(other) {
        return [
          this.foo++,
          this.foo,
          ++this.foo,
          this.foo,
          other.obj.foo++,
          other.obj.foo,
          ++other.obj.foo,
          other.obj.foo,
        ];
      }
    }
    const f = new Foo();
    const results = f.test({ obj: f });
    expect(results[0]).toBe(0);
    expect(results[1]).toBe(1);
    expect(results[2]).toBe(2);
    expect(results[3]).toBe(2);
    expect(results[4]).toBe(2);
    expect(results[5]).toBe(3);
    expect(results[6]).toBe(4);
    expect(results[7]).toBe(4);"
  `);
});

